 public Yaf_LoaderfalseYaf_Loader::registerNamespace
 stringarraynamespace
 stringpath&null;

Alias de Yaf_Loader::registerLocalNamespace.

  &reftitle.examples;

   Exemple avec Yaf_Loader::registerNamespace


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initLoader()
    {
        /* registerNamespace() est un alias de registerLocalNamespace() */
        Yaf_Loader::getInstance()->registerNamespace(
            "Vendor",
            APPLICATION_PATH . "/library/Vendor"
        );
    }
}

/* new Vendor_Payment_Gateway() est désormais recherchée dans
 * APPLICATION_PATH/library/Vendor/Payment/Gateway.php */
?>
